import { resolveApiBase } from "./api-base.js";
function finite(value) {
  if (value == null || value === "") return null;
  const num = typeof value === "number" ? value : Number(value);
  return Number.isFinite(num) ? num : null;
}

export function holePoint(value) {
  if (!value || typeof value !== "object") return null;
  const lat = finite(value.lat);
  const lng = finite(value.lng);
  if (lat == null || lng == null) return null;
  const label = typeof value.label === "string" ? value.label.trim() : "";
  return { lat, lng, label };
}

function haversineMeters(a, b) {
  const radiusMeters = 6371000;
  const rad = (degrees) => degrees * Math.PI / 180;
  const dLat = rad(b.lat - a.lat);
  const dLng = rad(b.lng - a.lng);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 2 * radiusMeters * Math.asin(Math.min(1, Math.sqrt(h)));
}

function haversineFt(a, b) {
  return Math.round(haversineMeters(a, b) * 3.28084);
}

export const CIRCLE1_M = 10;
export const CIRCLE2_M = 20;
export const HOLE_MAP_SIZE = { width: 640, height: 360 };
export const HOLE_MAP_COMPACT_SIZE = { width: 320, height: 180 };
export const HOLE_MAP_WATCH_SIZE = { width: 960, height: 1215 };
export const CIRCLE1_FT = CIRCLE1_M * 3.28084;
export const CIRCLE2_FT = CIRCLE2_M * 3.28084;
const FOCUS_C1_PAD_M = 16;
const FOCUS_C2_PAD_M = 28;

export function remainingFt(from, to) {
  const a = holePoint(from);
  const b = holePoint(to);
  if (!a || !b) return null;
  return haversineFt(a, b);
}

export function puttingCircle(from, to) {
  const a = holePoint(from);
  const b = holePoint(to);
  if (!a || !b) return null;
  const meters = haversineMeters(a, b);
  if (meters <= CIRCLE1_M) return "C1";
  if (meters <= CIRCLE2_M) return "C2";
  return null;
}

export function mapFocusFromRemaining(ft) {
  const n = finite(ft);
  if (n == null) return "hole";
  if (n <= CIRCLE1_FT) return "c1";
  if (n <= CIRCLE2_FT) return "c2";
  return "hole";
}

export function resolveMapFocus(userFocus, remainingFt) {
  if (userFocus === "hole" || userFocus === "c1" || userFocus === "c2") return userFocus;
  return mapFocusFromRemaining(remainingFt);
}

export function rangeHud({ from, to, mode, holeFt } = {}) {
  if (mode === "hole") {
    const ft = finite(holeFt);
    if (ft == null || ft <= 0) return null;
    return { caption: "hole", circle: null, ft: Math.round(ft), mode: "hole" };
  }
  const ft = remainingFt(from, to);
  if (ft == null) return null;
  const circle = puttingCircle(from, to);
  if (mode === "throw") {
    return { caption: "throw", circle, ft, mode: "throw" };
  }
  return {
    caption: circle ? "in " + circle : "to basket",
    circle,
    ft,
    mode: "remaining",
  };
}

export const GPS_REMAINING_MAX_FT = 2500;
export const GPS_WATCH_OPTIONS = {
  enableHighAccuracy: true,
  maximumAge: 15000,
  timeout: 60000,
};

export function gpsErrorPolicy(code, hasFix) {
  if (Number(code) === 1) {
    return { keepFix: true, restart: false, retryMs: 0, status: "denied" };
  }
  return {
    keepFix: true,
    restart: true,
    retryMs: 2000,
    status: hasFix ? "ready" : "watching",
  };
}

export function nextTeeHud(gps, nextHole) {
  const ft = remainingFt(gps, nextHole && nextHole.tee);
  if (ft == null || ft <= 0 || ft > GPS_REMAINING_MAX_FT) return null;
  return { caption: "next tee", ft };
}

export const THROW_MIN_FT = 8;

export function throwsStorageKey(roundCode, hole) {
  return "gvdg-throws:" + String(roundCode || "") + ":" + String(hole || "");
}

export function lastThrow(throws) {
  const rows = Array.isArray(throws) ? throws : [];
  return rows.length ? rows[rows.length - 1] : null;
}

export function addThrow(throws, point, minFt = THROW_MIN_FT) {
  const next = holePoint(point);
  const rows = Array.isArray(throws) ? throws.slice() : [];
  if (!next) return rows;
  const prev = lastThrow(rows);
  if (prev) {
    const gap = remainingFt(prev, next);
    if (gap != null && gap < minFt) return rows;
  }
  return rows.concat([{ lat: next.lat, lng: next.lng, n: rows.length + 1 }]);
}

export function undoThrow(throws) {
  const rows = Array.isArray(throws) ? throws : [];
  return rows.slice(0, -1).map((row, index) => ({ lat: row.lat, lng: row.lng, n: index + 1 }));
}

export function throwSegments(throws, tee) {
  const rows = Array.isArray(throws) ? throws : [];
  const points = [];
  const start = holePoint(tee);
  if (start) points.push(start);
  rows.forEach((row) => points.push(row));
  const segs = [];
  for (let i = 1; i < points.length; i += 1) {
    segs.push({
      a: points[i - 1],
      b: points[i],
      ft: remainingFt(points[i - 1], points[i]),
      n: i,
    });
  }
  return segs;
}

export function flightArc(from, to, kind = "lie") {
  if (!from || !to) return null;
  const x1 = Number(from.x);
  const y1 = Number(from.y);
  const x2 = Number(to.x);
  const y2 = Number(to.y);
  if (![x1, y1, x2, y2].every(Number.isFinite)) return null;
  const dx = x2 - x1;
  const dy = y2 - y1;
  const len = Math.hypot(dx, dy);
  if (len < 2) return null;
  let nx = -dy / len;
  let ny = dx / len;
  if (ny > 0) {
    nx = -nx;
    ny = -ny;
  }
  const loft = Math.max(6, Math.min(kind === "putt" ? 16 : 18, len * 0.16));
  const qx = (x1 + x2) / 2 + nx * loft;
  const qy = (y1 + y2) / 2 + ny * loft;
  return {
    kind,
    ms: Math.round(2000 + Math.min(len * 8, 1800)),
    path: `M ${x1.toFixed(1)} ${y1.toFixed(1)} Q ${qx.toFixed(1)} ${qy.toFixed(1)} ${x2.toFixed(1)} ${y2.toFixed(1)}`,
    from: { x: x1, y: y1 },
    q: { x: qx, y: qy },
    to: { x: x2, y: y2 },
  };
}

export function flightPoint(arc, t) {
  if (!arc || !arc.from || !arc.to) return null;
  const clamped = Math.max(0, Math.min(1, Number(t) || 0));
  const q = arc.q;
  if (!q || !Number.isFinite(q.x) || !Number.isFinite(q.y)) {
    return {
      x: arc.from.x + (arc.to.x - arc.from.x) * clamped,
      y: arc.from.y + (arc.to.y - arc.from.y) * clamped,
    };
  }
  const u = 1 - clamped;
  return {
    x: u * u * arc.from.x + 2 * u * clamped * q.x + clamped * clamped * arc.to.x,
    y: u * u * arc.from.y + 2 * u * clamped * q.y + clamped * clamped * arc.to.y,
  };
}

export function lastThrowHud(throws, tee) {
  const segs = throwSegments(throws, tee);
  const last = segs[segs.length - 1];
  if (!last || last.ft == null) return null;
  return { caption: "throw " + last.n, ft: last.ft };
}

export function readThrows(storage, roundCode, hole) {
  try {
    const raw = storage && storage.getItem(throwsStorageKey(roundCode, hole));
    const parsed = raw ? JSON.parse(raw) : [];
    if (!Array.isArray(parsed)) return [];
    return parsed
      .map((row) => holePoint(row))
      .filter(Boolean)
      .map((row, index) => ({ lat: row.lat, lng: row.lng, n: index + 1 }));
  } catch {
    return [];
  }
}

export function writeThrows(storage, roundCode, hole, throws) {
  if (!storage || typeof storage.setItem !== "function") return false;
  try {
    storage.setItem(throwsStorageKey(roundCode, hole), JSON.stringify(Array.isArray(throws) ? throws : []));
    return true;
  } catch {
    return false;
  }
}

export function readAllThrows(storage, roundCode, holes) {
  const out = {};
  for (const hole of Array.isArray(holes) ? holes : []) {
    const n = hole && (hole.hole != null ? hole.hole : hole);
    if (n == null) continue;
    const rows = readThrows(storage, roundCode, n);
    if (rows.length) out[n] = rows;
  }
  return out;
}

export function gpsHudPrompt(status, mode) {
  if (mode === "remaining" || mode === "throw") return "";
  if (status === "denied") return "GPS blocked";
  if (status === "watching") return "Finding GPS…";
  if (status === "unavailable") return "GPS unavailable";
  if (status === "ready" && mode !== "hole") return "";
  return "Tap for GPS";
}

export function withSelfLocation(players, gps, self) {
  const rows = Array.isArray(players) ? players.slice() : [];
  if (!gps || !Number.isFinite(gps.lat) || !Number.isFinite(gps.lng)) return rows;
  const selfIndex = self && Number.isInteger(self.index) ? self.index : null;
  const selfInitials = playerMapInitials(self && (self.initials || self.name));
  const idx = rows.findIndex((row) => {
    if (!row) return false;
    if (selfIndex != null && row.index === selfIndex) return true;
    if (row.relClass === "self") return true;
    return false;
  });
  if (idx >= 0) {
    const current = rows[idx];
    rows[idx] = {
      ...current,
      initials: playerMapInitials(current.initials) || selfInitials || "ME",
      lat: gps.lat,
      lng: gps.lng,
      relClass: "self",
    };
    return rows;
  }
  const row = {
    index: selfIndex,
    initials: selfInitials || "ME",
    lat: gps.lat,
    lng: gps.lng,
    relClass: "self",
  };
  if (self && self.photo) row.photo = self.photo;
  return rows.concat([row]);
}

function playerMapInitials(value) {
  const text = String(value || "").trim();
  if (!text) return "";
  if (/^[A-Za-z]{1,3}$/.test(text)) return text.toUpperCase();
  const parts = text.split(/\s+/).filter(Boolean);
  if (!parts.length) return "";
  const first = parts[0][0] || "";
  const last = parts.length > 1 ? (parts[parts.length - 1][0] || "") : "";
  return (first + last).toUpperCase();
}

export function currentRangeHud(hole, gps, measure, lastLie) {
  const holeFt = finite(hole && hole.distance_ft);
  const holeHud = rangeHud({ holeFt, mode: "hole" });
  let primary = null;
  if (measure && measure.a && measure.b) {
    primary = rangeHud({ from: measure.a, mode: "throw", to: measure.b });
  } else if (measure && measure.a && gps) {
    primary = rangeHud({ from: measure.a, mode: "throw", to: gps });
  } else if (measure && measure.a && hole && hole.target) {
    primary = rangeHud({ from: measure.a, to: hole.target });
  } else if (gps && hole && hole.target) {
    primary = rangeHud({ from: gps, to: hole.target });
  } else if (lastLie && hole && hole.target) {
    primary = rangeHud({ from: lastLie, to: hole.target });
  }
  if (!primary) return holeHud;
  if (holeFt == null || holeFt <= 0) return primary;
  return { ...primary, holeFt: Math.round(holeFt) };
}


export function headingDeg(from, to) {
  const dLng = (to.lng - from.lng) * Math.PI / 180;
  const lat1 = from.lat * Math.PI / 180;
  const lat2 = to.lat * Math.PI / 180;
  const y = Math.sin(dLng) * Math.cos(lat2);
  const x = Math.cos(lat1) * Math.sin(lat2) - Math.sin(lat1) * Math.cos(lat2) * Math.cos(dLng);
  return ((Math.atan2(y, x) * 180 / Math.PI) + 360) % 360;
}

export function teePadRotationDeg(tee, basket) {
  if (!tee || !basket) return 0;
  const dx = Number(basket.x) - Number(tee.x);
  const dy = Number(basket.y) - Number(tee.y);
  if (!Number.isFinite(dx) || !Number.isFinite(dy) || (dx === 0 && dy === 0)) return 0;
  // Local pad +Y is the long throwing axis. Align it with the on-screen
  // tee→basket line, not geographic heading (the 16:9 map is stretched).
  return Number(((Math.atan2(dy, dx) * 180 / Math.PI) - 90).toFixed(2));
}

export function windBlowToDeg(windFromDeg) {
  const from = finite(windFromDeg);
  return from == null ? null : (from + 180) % 360;
}

const SATELLITE_EXPORT = "https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/export";
export const SATELLITE_CREDIT = "Imagery: Esri, Maxar, Earthstar Geographics";
const BOUNDS_PAD_RATIO = 0.7;
const BOUNDS_MIN_DEG = 0.00032;

function paddedBounds(tee, basket) {
  const minLat = Math.min(tee.lat, basket.lat);
  const maxLat = Math.max(tee.lat, basket.lat);
  const minLng = Math.min(tee.lng, basket.lng);
  const maxLng = Math.max(tee.lng, basket.lng);
  const midLat = (minLat + maxLat) / 2;
  const latPad = Math.max((maxLat - minLat) * BOUNDS_PAD_RATIO, BOUNDS_MIN_DEG);
  const lngPad = Math.max((maxLng - minLng) * BOUNDS_PAD_RATIO, BOUNDS_MIN_DEG / Math.max(Math.cos(midLat * Math.PI / 180), 0.2));
  return {
    minLat: minLat - latPad,
    maxLat: maxLat + latPad,
    minLng: minLng - lngPad,
    maxLng: maxLng + lngPad,
  };
}

function focusBounds(basket, radiusMeters) {
  const meters = finite(radiusMeters) || FOCUS_C2_PAD_M;
  const dLat = meters / 111320;
  const cosLat = Math.max(Math.cos(basket.lat * Math.PI / 180), 0.2);
  const dLng = meters / (111320 * cosLat);
  return {
    minLat: basket.lat - dLat,
    maxLat: basket.lat + dLat,
    minLng: basket.lng - dLng,
    maxLng: basket.lng + dLng,
  };
}

function boundsForFocus(tee, basket, focus) {
  if (focus === "c1") return focusBounds(basket, FOCUS_C1_PAD_M);
  if (focus === "c2") return focusBounds(basket, FOCUS_C2_PAD_M);
  return paddedBounds(tee, basket);
}

// ArcGIS adjusts its export extent to the image aspect ratio. Use that extent
// for the map overlay and inverse pointer projection too.
function fitBoundsToSize(bounds, width, height) {
  const spanLng = bounds.maxLng - bounds.minLng;
  const spanLat = bounds.maxLat - bounds.minLat;
  const degreesPerPixel = Math.max(spanLng / width, spanLat / height);
  const lngPad = (width * degreesPerPixel - spanLng) / 2;
  const latPad = (height * degreesPerPixel - spanLat) / 2;
  return {
    minLng: bounds.minLng - lngPad,
    maxLng: bounds.maxLng + lngPad,
    minLat: bounds.minLat - latPad,
    maxLat: bounds.maxLat + latPad,
  };
}

export function satelliteImageUrl(bounds, width, height) {
  if (!bounds) return "";
  const spanLng = bounds.maxLng - bounds.minLng;
  const spanLat = bounds.maxLat - bounds.minLat;
  if (!(spanLng > 0) || !(spanLat > 0)) return "";
  const params = new URLSearchParams({
    bbox: [bounds.minLng, bounds.minLat, bounds.maxLng, bounds.maxLat].map((value) => value.toFixed(7)).join(","),
    bboxSR: "4326",
    imageSR: "4326",
    size: Math.round(width) + "," + Math.round(height),
    format: "jpg",
    f: "image",
  });
  return SATELLITE_EXPORT + "?" + params.toString();
}

const SATELLITE_TILE = "https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/";
const TILE_PX = 256;

function worldX(lng, zoom) {
  return ((lng + 180) / 360) * 2 ** zoom;
}

function worldY(lat, zoom) {
  const rad = lat * Math.PI / 180;
  const merc = Math.log(Math.tan(Math.PI / 4 + rad / 2));
  return ((1 - merc / Math.PI) / 2) * 2 ** zoom;
}

export const SATELLITE_MAX_ZOOM = 19;
export const SATELLITE_MAX_TILES = 24;

function tileSpan(bounds, zoom) {
  const cols = Math.floor(worldX(bounds.maxLng, zoom)) - Math.floor(worldX(bounds.minLng, zoom)) + 1;
  const rows = Math.floor(worldY(bounds.minLat, zoom)) - Math.floor(worldY(bounds.maxLat, zoom)) + 1;
  return cols * rows;
}

/**
 * The tile zoom for a map: the sharpest (up to 19) that covers it in SATELLITE_MAX_TILES tiles. It depends on the
 * place, not the screen, so the scorecard, the replay and the preloads all ask for the same (cached) tiles.
 */
export function satelliteTileZoom(bounds) {
  for (let z = SATELLITE_MAX_ZOOM; z > 12; z -= 1) {
    if (tileSpan(bounds, z) <= SATELLITE_MAX_TILES) return z;
  }
  return 12;
}

/**
 * Satellite tiles covering the map, placed in percent of the map frame. Tiles are pre-made on Esri's CDN: they load
 * in parallel in well under a second and are shared between holes and zooms, where the export image is rendered
 * on demand for each hole, zoom and size (several seconds). The export stays as the fallback.
 */
export function satelliteTileLayers(bounds, width, height) {
  if (!bounds) return [];
  const spanLng = bounds.maxLng - bounds.minLng;
  const spanLat = bounds.maxLat - bounds.minLat;
  if (!(spanLng > 0) || !(spanLat > 0)) return [];
  const frameW = Math.max(1, Number(width) || 640);
  const frameH = Math.max(1, Number(height) || 360);
  const zoom = satelliteTileZoom(bounds);
  const x0 = worldX(bounds.minLng, zoom) * TILE_PX;
  const y0 = worldY(bounds.maxLat, zoom) * TILE_PX;
  const x1 = worldX(bounds.maxLng, zoom) * TILE_PX;
  const y1 = worldY(bounds.minLat, zoom) * TILE_PX;
  const scaleX = frameW / Math.max(x1 - x0, 1);
  const scaleY = frameH / Math.max(y1 - y0, 1);
  const col0 = Math.floor(worldX(bounds.minLng, zoom));
  const col1 = Math.floor(worldX(bounds.maxLng, zoom));
  const row0 = Math.floor(worldY(bounds.maxLat, zoom));
  const row1 = Math.floor(worldY(bounds.minLat, zoom));
  const tiles = [];
  for (let row = row0; row <= row1; row += 1) {
    for (let col = col0; col <= col1; col += 1) {
      if (tiles.length >= SATELLITE_MAX_TILES) return tiles;
      const left = ((col * TILE_PX - x0) * scaleX / frameW) * 100;
      const top = ((row * TILE_PX - y0) * scaleY / frameH) * 100;
      const tileW = (TILE_PX * scaleX / frameW) * 100;
      const tileH = (TILE_PX * scaleY / frameH) * 100;
      tiles.push({
        url: SATELLITE_TILE + zoom + "/" + row + "/" + col,
        left: Number(left.toFixed(3)),
        top: Number(top.toFixed(3)),
        width: Number(tileW.toFixed(3)),
        height: Number(tileH.toFixed(3)),
      });
    }
  }
  return tiles;
}

function mapXy(bounds, width, height, lng, lat) {
  const spanLng = Math.max(bounds.maxLng - bounds.minLng, 1e-7);
  const spanLat = Math.max(bounds.maxLat - bounds.minLat, 1e-7);
  return {
    x: Number((((lng - bounds.minLng) / spanLng) * width).toFixed(2)),
    y: Number((((bounds.maxLat - lat) / spanLat) * height).toFixed(2)),
  };
}

export function circleEllipse(map, radiusMeters) {
  const basket = holePoint(map && map.basket);
  if (!map || !map.bounds || !basket) return null;
  const meters = finite(radiusMeters);
  if (meters == null || meters <= 0) return null;
  const dLat = meters / 111320;
  const cosLat = Math.max(Math.cos(basket.lat * Math.PI / 180), 0.2);
  const dLng = meters / (111320 * cosLat);
  const north = mapXy(map.bounds, map.width, map.height, basket.lng, basket.lat + dLat);
  const east = mapXy(map.bounds, map.width, map.height, basket.lng + dLng, basket.lat);
  const rx = Math.abs(east.x - map.basket.x);
  const ry = Math.abs(north.y - map.basket.y);
  if (!(rx > 0) || !(ry > 0)) return null;
  return {
    cx: map.basket.x,
    cy: map.basket.y,
    rx: Number(rx.toFixed(2)),
    ry: Number(ry.toFixed(2)),
  };
}

export function latLngFromMapPoint(map, x, y) {
  if (!map || !map.bounds) return null;
  const spanLng = Math.max(map.bounds.maxLng - map.bounds.minLng, 1e-7);
  const spanLat = Math.max(map.bounds.maxLat - map.bounds.minLat, 1e-7);
  const width = map.width || 1;
  const height = map.height || 1;
  const lng = map.bounds.minLng + (Number(x) / width) * spanLng;
  const lat = map.bounds.maxLat - (Number(y) / height) * spanLat;
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  return { lat, lng };
}

export function projectHoleMap(hole, options = {}) {
  const tee = holePoint(hole && hole.tee);
  const basket = holePoint(hole && hole.target);
  if (!tee || !basket) return null;
  if (Math.abs(tee.lat - basket.lat) < 1e-8 && Math.abs(tee.lng - basket.lng) < 1e-8) return null;

  const width = finite(options.width) || 640;
  const height = finite(options.height) || 360;
  const focus = options.focus === "c1" || options.focus === "c2" ? options.focus : "hole";
  const focusBounds = boundsForFocus(tee, basket, focus);
  const bounds = options.fitViewport ? fitBoundsToSize(focusBounds, width, height) : focusBounds;

  const teePt = { ...mapXy(bounds, width, height, tee.lng, tee.lat), lat: tee.lat, lng: tee.lng, label: tee.label || "Tee" };
  const basketPt = { ...mapXy(bounds, width, height, basket.lng, basket.lat), lat: basket.lat, lng: basket.lng, label: basket.label || "Basket" };
  const distanceFt = finite(hole && hole.distance_ft) || haversineFt(tee, basket);
  const windFrom = finite(options.windFromDeg);
  return {
    width,
    height,
    bounds,
    focus,
    satelliteUrl: satelliteImageUrl(bounds, width, height),
    tee: teePt,
    basket: basketPt,
    headingDeg: headingDeg(tee, basket),
    teeRotationDeg: teePadRotationDeg(teePt, basketPt),
    distanceFt,
    windBlowToDeg: windBlowToDeg(windFrom),
    windFromDeg: windFrom,
    circle1: circleEllipse({ bounds, width, height, basket: basketPt }, CIRCLE1_M),
    circle2: circleEllipse({ bounds, width, height, basket: basketPt }, CIRCLE2_M),
  };
}

const LOOSE_PAD_M = 90;

function boundsAround(points, meters) {
  let minLat = Infinity;
  let maxLat = -Infinity;
  let minLng = Infinity;
  let maxLng = -Infinity;
  for (const point of points) {
    const dLat = meters / 111320;
    const dLng = meters / (111320 * Math.max(Math.cos(point.lat * Math.PI / 180), 0.2));
    minLat = Math.min(minLat, point.lat - dLat);
    maxLat = Math.max(maxLat, point.lat + dLat);
    minLng = Math.min(minLng, point.lng - dLng);
    maxLng = Math.max(maxLng, point.lng + dLng);
  }
  return { minLat, maxLat, minLng, maxLng };
}

function uniquePoints(points) {
  const out = [];
  for (const point of points) {
    if (!point) continue;
    if (out.some((row) => Math.abs(row.lat - point.lat) < 1e-7 && Math.abs(row.lng - point.lng) < 1e-7)) continue;
    out.push(point);
  }
  return out;
}

/** Satellite frame for a hole that does not have both a tee and a basket yet.
 *  Device GPS is never a camera anchor — that pulled the picture onto the
 *  phone and reloaded imagery on every fix. The player dot is drawn later
 *  only if it falls inside this frame.
 */
export function projectLooseHoleMap(hole, options = {}) {
  const strict = projectHoleMap(hole, options);
  if (strict) return strict;
  const tee = holePoint(hole && hole.tee);
  const basket = holePoint(hole && hole.target);
  const anchors = uniquePoints([tee, basket]);
  if (!anchors.length) return null;
  const width = finite(options.width) || 640;
  const height = finite(options.height) || 360;
  const anchorBounds = anchors.length === 1
    ? boundsAround(anchors, LOOSE_PAD_M)
    : paddedBounds(
      { lat: Math.min(...anchors.map((point) => point.lat)), lng: Math.min(...anchors.map((point) => point.lng)) },
      { lat: Math.max(...anchors.map((point) => point.lat)), lng: Math.max(...anchors.map((point) => point.lng)) },
    );
  const bounds = options.fitViewport ? fitBoundsToSize(anchorBounds, width, height) : anchorBounds;
  const place = (point, label) => (
    point
      ? { ...mapXy(bounds, width, height, point.lng, point.lat), lat: point.lat, lng: point.lng, label }
      : null
  );
  const teePt = place(tee, (tee && tee.label) || "Tee");
  const basketPt = place(basket, (basket && basket.label) || "Basket");
  const windFrom = finite(options.windFromDeg);
  return {
    width,
    height,
    bounds,
    focus: "hole",
    loose: true,
    satelliteUrl: satelliteImageUrl(bounds, width, height),
    tee: teePt,
    basket: basketPt,
    headingDeg: tee && basket ? headingDeg(tee, basket) : null,
    teeRotationDeg: teePt && basketPt ? teePadRotationDeg(teePt, basketPt) : 0,
    distanceFt: tee && basket ? haversineFt(tee, basket) : (finite(hole && hole.distance_ft) || null),
    windBlowToDeg: windBlowToDeg(windFrom),
    windFromDeg: windFrom,
    circle1: basketPt ? circleEllipse({ bounds, width, height, basket: basketPt }, CIRCLE1_M) : null,
    circle2: basketPt ? circleEllipse({ bounds, width, height, basket: basketPt }, CIRCLE2_M) : null,
  };
}


export function holeMapLabel(map, holeNumber) {
  if (!map) return "";
  const hole = holeNumber ? `Hole ${holeNumber} map` : "Hole map";
  const distance = map.distanceFt ? `, ${map.distanceFt} ft` : "";
  const wind = map.windFromDeg == null ? "" : `, wind from ${Math.round(map.windFromDeg)} degrees`;
  return `${hole}${distance}${wind}`;
}

export function projectMapPoint(map, lat, lng) {
  if (!map || !map.bounds) return null;
  const pointLat = finite(lat);
  const pointLng = finite(lng);
  if (pointLat == null || pointLng == null) return null;
  const pad = 0.00012;
  if (pointLat < map.bounds.minLat - pad || pointLat > map.bounds.maxLat + pad) return null;
  if (pointLng < map.bounds.minLng - pad || pointLng > map.bounds.maxLng + pad) return null;
  return mapXy(map.bounds, map.width, map.height, pointLng, pointLat);
}


export function playerPhotoSrc(value) {
  if (typeof value !== "string") return "";
  const photo = value.trim();
  if (!photo || photo.length > 200000) return "";
  // A member's photo as a signed link from the Worker (live rounds send this instead of the image): served from the
  // API host and cached for good.
  if (/^\/member-photos\/[A-Za-z0-9_.-]{1,80}\/[a-f0-9]{16}\?v=[a-f0-9]{12}$/.test(photo)) return resolveApiBase() + photo;
  if (/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(photo)) return photo;
  // pdga.com pictures (older profiles) are not shown: PDGA's content stays on pdga.com.
  return "";
}

export function playerMarksOnMap(map, players) {
  const rows = Array.isArray(players) ? players : [];
  const marks = [];
  rows.forEach((player) => {
    const pt = projectMapPoint(map, player && player.lat, player && player.lng);
    if (!pt) return;
    const initials = String((player && player.initials) || "").trim().slice(0, 3).toUpperCase();
    if (!initials) return;
    marks.push({
      key: player.index != null ? String(player.index) : `${initials}:${pt.x}:${pt.y}`,
      initials,
      x: pt.x,
      y: pt.y,
      strokes: player.strokes,
      label: player.label,
      relClass: player.relClass,
      stale: player.fresh === false,
      photo: playerPhotoSrc(player.photo),
    });
  });
  marks.sort((a, b) => a.x - b.x || a.y - b.y);
  for (let i = 1; i < marks.length; i += 1) {
    const prev = marks[i - 1];
    const dx = marks[i].x - prev.x;
    const dy = marks[i].y - prev.y;
    if (dx * dx + dy * dy < 256) {
      marks[i] = { ...marks[i], x: marks[i].x + 14, y: marks[i].y - 10 };
    }
  }
  return marks;
}

export function scoreChipAnchor(mark, width, height) {
  const spanX = width > 0 ? width : 1;
  const spanY = height > 0 ? height : 1;
  return {
    x: (mark && mark.x) / spanX > 0.72 ? "left" : "right",
    y: (mark && mark.y) / spanY < 0.18 ? "below" : "above",
  };
}
