import React from "react";
import { KarmaChip } from "../shared/karma.js";

import { playersMatch } from "../shared/player-identity.js";
import { useSettledWhileLoading } from "../shared/settled-state.js";
import { configuredNames, useAdminRegistrationControlsState } from "./registration-controls.js";

const h = React.createElement;

const EMPTY_MEMBERS = { members: [], status: "loading" };
const EMPTY_ROSTER = { registrations: [], manualPlayers: [] };

function objectOrEmpty(value) {
  return value && typeof value === "object" ? value : {};
}

function normalizeText(value, fallback = "") {
  return typeof value === "string" ? value : fallback;
}

function memberIdOf(value) {
  const source = objectOrEmpty(value);
  return normalizeText(source.memberId || source.member_id).trim();
}

function playerNameOf(value) {
  return normalizeText(objectOrEmpty(value).name).trim();
}

export function availableClubMembers(members, registrations, query, extraPlayers = []) {
  const roster = [
    ...(Array.isArray(registrations) ? registrations : []),
    ...(Array.isArray(extraPlayers) ? extraPlayers : []),
  ];
  const registered = new Set(roster.map(memberIdOf).filter(Boolean));
  const q = normalizeText(query).trim().toLowerCase();
  return (Array.isArray(members) ? members : []).flatMap((member) => {
    const source = objectOrEmpty(member);
    const memberId = memberIdOf(source);
    if (!memberId || registered.has(memberId)) return [];
    const name = normalizeText(source.name, memberId);
    if (roster.some((row) => playersMatch(name, playerNameOf(row)))) return [];
    const pdgaNo = normalizeText(source.pdgaNo || source.pdga_no);
    const udisc = normalizeText(source.udisc);
    if (q) {
      const haystack = `${name} ${memberId} ${pdgaNo} ${udisc}`.toLowerCase();
      if (!haystack.includes(q)) return [];
    }
    return [{ memberId, name, pdgaNo, udisc }];
  });
}

function requestId() {
  return `register-members-${Date.now()}`;
}

function dispatchRequest(name, detail) {
  window.dispatchEvent(new CustomEvent(name, { detail }));
}

function memberMeta(member) {
  const bits = [];
  if (member.pdgaNo) bits.push(`#${member.pdgaNo}`);
  if (member.udisc) bits.push(member.udisc);
  return bits.join(" / ");
}

export function AdminRegistrationMemberPicker({ eventStatus }) {
  const [membersState, setMembersState] = React.useState(EMPTY_MEMBERS);
  const [registrations, setRegistrations] = React.useState([]);
  const [manualPlayers, setManualPlayers] = React.useState([]);
  const [query, setQuery] = React.useState("");
  const [selected, setSelected] = React.useState(() => new Set());
  const [division, setDivision] = React.useState("");
  const [team, setTeam] = React.useState("");
  const [error, setError] = React.useState("");
  const [ctp, setCtp] = React.useState(false);
  const [ace, setAce] = React.useState(false);
  const [paidEntry, setPaidEntry] = React.useState(false);
  const [pendingRequest, setPendingRequest] = React.useState("");

  React.useEffect(() => {
    function updateMembers(event) {
      const detail = event.detail && typeof event.detail === "object" ? event.detail : EMPTY_MEMBERS;
      setMembersState({
        members: Array.isArray(detail.members) ? detail.members : [],
        status: detail.status === "error" ? "error" : detail.status === "loading" ? "loading" : "ready",
      });
    }
    function updateRoster(event) {
      const detail = event.detail && typeof event.detail === "object" ? event.detail : EMPTY_ROSTER;
      setRegistrations(Array.isArray(detail.registrations) ? detail.registrations : []);
      setManualPlayers(Array.isArray(detail.manualPlayers) ? detail.manualPlayers : []);
    }
    window.addEventListener("gvdg:admin-registration-members-list", updateMembers);
    window.addEventListener("gvdg:admin-registration-roster", updateRoster);
    return () => {
      window.removeEventListener("gvdg:admin-registration-members-list", updateMembers);
      window.removeEventListener("gvdg:admin-registration-roster", updateRoster);
    };
  }, []);

  React.useEffect(() => {
    if (!pendingRequest) return undefined;
    function update(event) {
      if (event.detail?.requestId !== pendingRequest) return;
      setPendingRequest("");
      if (event.detail?.ok === true) {
        setSelected(new Set());
        setQuery("");
      }
    }
    window.addEventListener("gvdg:admin-registration-members-add-result", update);
    return () => window.removeEventListener("gvdg:admin-registration-members-add-result", update);
  }, [pendingRequest]);

  const rosterMembers = useSettledWhileLoading(membersState);
  const controls = useAdminRegistrationControlsState();
  const divisions = configuredNames(controls.config && controls.config.divisions);
  const teams = configuredNames(controls.config && controls.config.teams);
  const teamEvent = String(controls.config && controls.config.play_format || "").toLowerCase() === "teams";
  const unregistered = availableClubMembers(rosterMembers.members, registrations, "", manualPlayers);
  const available = availableClubMembers(rosterMembers.members, registrations, query, manualPlayers);
  const unregisteredIds = new Set(unregistered.map((member) => member.memberId));
  const selectedIds = [...selected].filter((id) => unregisteredIds.has(id));
  const busy = Boolean(pendingRequest);
  const live = eventStatus === "live";

  function toggleMember(memberId) {
    const next = new Set(selectedIds);
    if (next.has(memberId)) next.delete(memberId);
    else next.add(memberId);
    setSelected(next);
    if (next.size <= 40) setError("");
  }

  function selectAllShown() {
    const next = new Set(selectedIds);
    let hitCap = false;
    for (const member of available) {
      if (next.has(member.memberId)) continue;
      if (next.size >= 40) {
        hitCap = true;
        break;
      }
      next.add(member.memberId);
    }
    setSelected(next);
    setError(hitCap ? "Select 40 or fewer members at a time." : "");
  }

  function submit(event) {
    event.preventDefault();
    if (busy) return;
    if (selectedIds.length > 40) {
      setError("Select 40 or fewer members at a time.");
      return;
    }
    if (teamEvent && teams.length && !team.trim()) {
      setError("Pick a team before adding these players.");
      return;
    }
    const id = requestId();
    setPendingRequest(id);
    setError("");
    dispatchRequest("gvdg:admin-registration-members-add-request", {
      body: {
        addons: { ctp, ace },
        division: division.trim() || null,
        member_ids: selectedIds,
        paid_entry: paidEntry,
        team: team.trim() || null,
      },
      requestId: id,
      valid: selectedIds.length > 0 && (!(teamEvent && teams.length) || Boolean(team.trim())),
    });
  }

  const listBody = rosterMembers.status === "loading"
    ? h("p", { className: "al-note rg-member-empty", key: "loading", role: "status" }, "Loading club members…")
    : rosterMembers.status === "error"
      ? h("p", { className: "al-note err rg-member-empty", key: "error", role: "alert" }, "Unable to load club members.")
      : available.length
        ? available.map((member) => h("label", {
          className: "rg-member-option",
          key: member.memberId,
        }, [
          h("input", {
            checked: selected.has(member.memberId),
            disabled: busy,
            key: "check",
            onChange: () => toggleMember(member.memberId),
            type: "checkbox",
          }),
          h("span", { key: "name" }, [member.name, h(KarmaChip, { key: "karma", memberId: member.memberId })]),
          memberMeta(member) ? h("span", { className: "rg-member-meta", key: "meta" }, memberMeta(member)) : null,
        ]))
        : h("p", { className: "al-note rg-member-empty", key: "empty", role: "status" }, query.trim()
          ? "No matching members left to add."
          : "Every club member is already registered.");

  return h("div", {
    className: "al-section",
    "data-react-admin-registration-member-picker": rosterMembers.status,
    style: { marginTop: "1rem" },
  }, [
    h("h4", { className: "al-h", key: "title" }, "Add club members"),
    h("p", { className: "al-note", key: "note" }, live
      ? "Once live scoring starts, add a player on the scoring card instead. You can still add members here if scoring has not started yet."
      : "Search the roster and add members who paid cash at the event. They show up as registered players, not walk-ons."),
    h("div", { className: "al-row", key: "search", style: { marginTop: "0.5rem" } }, [
      h("input", {
        "aria-label": "Search club members",
        className: "rg-member-search",
        disabled: busy || rosterMembers.status === "loading",
        id: "rgMemberSearch",
        key: "query",
        onChange: (event) => setQuery(event.target.value),
        placeholder: "Search name, PDGA, or UDisc",
        type: "search",
        value: query,
      }),
      h("button", {
        className: "admin-btn secondary",
        disabled: busy || !available.length,
        key: "all",
        onClick: selectAllShown,
        type: "button",
      }, "Select all shown"),
      h("button", {
        className: "admin-btn secondary",
        disabled: busy || !selectedIds.length,
        key: "clear",
        onClick: () => {
          setSelected(new Set());
          setError("");
        },
        type: "button",
      }, "Clear"),
    ]),
    h("div", { className: "rg-member-list", key: "list" }, listBody),
    h("form", { className: "al-row", key: "form", onSubmit: submit }, [
      h(divisions.length ? "select" : "input", {
        disabled: busy,
        id: "rgMemberDivision",
        "aria-label": "Division (optional)",
        key: "division",
        maxLength: divisions.length ? undefined : 40,
        onChange: (event) => setDivision(event.target.value),
        placeholder: "division (optional)",
        value: division,
      }, divisions.length ? [
        h("option", { key: "empty", value: "" }, "division (optional)"),
        ...(division && !divisions.includes(division) ? [h("option", { key: division, value: division }, division)] : []),
        ...divisions.map((name) => h("option", { key: name, value: name }, name)),
      ] : null),
      teamEvent ? h(teams.length ? "select" : "input", {
        disabled: busy,
        id: "rgMemberTeam",
        "aria-label": "Team",
        key: "team",
        maxLength: teams.length ? undefined : 40,
        onChange: (event) => setTeam(event.target.value),
        placeholder: teams.length ? "Team" : "Add teams in settings",
        value: team,
      }, teams.length ? [
        h("option", { key: "empty", value: "" }, "Team"),
        ...(team && !teams.includes(team) ? [h("option", { key: team, value: team }, team)] : []),
        ...teams.map((name) => h("option", { key: name, value: name }, name)),
      ] : null) : null,
      h("label", { className: "register-addon", htmlFor: "rgMemberAddonCtp", key: "ctp" }, [
        h("input", {
          checked: ctp,
          disabled: busy,
          id: "rgMemberAddonCtp",
          key: "input",
          onChange: (event) => setCtp(event.target.checked),
          type: "checkbox",
        }),
        " CTP",
      ]),
      h("label", { className: "register-addon", htmlFor: "rgMemberAddonAce", key: "ace" }, [
        h("input", {
          checked: ace,
          disabled: busy,
          id: "rgMemberAddonAce",
          key: "input",
          onChange: (event) => setAce(event.target.checked),
          type: "checkbox",
        }),
        " Ace pot",
      ]),
      h("label", { className: "register-addon", htmlFor: "rgMemberPaid", key: "paid" }, [
        h("input", {
          checked: paidEntry,
          disabled: busy,
          id: "rgMemberPaid",
          key: "input",
          onChange: (event) => setPaidEntry(event.target.checked),
          type: "checkbox",
        }),
        " Mark selected as paid (cash collected)",
      ]),
      h("button", {
        className: "admin-btn",
        disabled: busy || !selectedIds.length,
        id: "rgMemberAddBtn",
        key: "submit",
        type: "submit",
      }, busy ? "Adding…" : (selectedIds.length ? `Add selected (${selectedIds.length})` : "Add selected")),
    ]),
    error ? h("p", { className: "al-note err", key: "error", role: "alert" }, error) : null,
  ]);
}
